import{_ as s,o as p,c as e,a2 as t}from"./chunks/framework.EUByU7Iq.js";const z=JSON.parse('{"title":"哀命","description":"","frontmatter":{"title":"哀命","date":"2026-11-24T00:00:00.000Z","seq":36,"categories":["美文","楚辞"],"collection":"《楚辞》","tags":["楚辞","先秦"],"poem":true,"poem_quote":false,"author":"东方朔","source_book":"楚辞","prev":{"text":"自悲","link":"/blogs/楚辞/自悲.html"},"next":{"text":"谬谏","link":"/blogs/楚辞/谬谏.html"}},"headers":[],"relativePath":"blogs/楚辞/哀命.md","filePath":"blogs/楚辞/哀命.md"}'),o={name:"blogs/楚辞/哀命.md"};function l(n,a,c,m,r,_){return p(),e("div",null,[...a[0]||(a[0]=[t('<h1 id="哀命" tabindex="-1">哀命 <a class="header-anchor" href="#哀命" aria-label="Permalink to &quot;哀命&quot;">​</a></h1><p class="poem-meta">先秦 · 东方朔　·　七谏</p><div class="poem"><p class="poem-stanza">哀时命之不合兮，伤楚国之多忧。</p><p class="poem-stanza">内怀情之洁白兮，遭乱世而离尤。</p><p class="poem-stanza">恶耿介之直行兮，世溷浊而不知。</p><p class="poem-stanza">何君臣之相失兮，上沅湘而分离。</p><p class="poem-stanza">测汨罗之湘水兮，知时固而不反。</p><p class="poem-stanza">伤离散之交乱兮，遂侧身而既远。</p><p class="poem-stanza">处玄舍之幽门兮，穴岩石而窟伏。</p><p class="poem-stanza">从水蛟而为徙兮，与神龙乎休息。</p><p class="poem-stanza">何山石之崭岩兮，灵魂屈而偃蹇。</p><p class="poem-stanza">含素水而蒙深兮，日眇眇而既远。</p><p class="poem-stanza">哀形体之离解兮，神罔两而无舍。</p><p class="poem-stanza">惟椒兰之不反兮，魂迷惑而不知路。</p><p class="poem-stanza">愿无过之设行兮，虽灭没之自乐。</p><p class="poem-stanza">痛楚国之流亡兮，哀灵修之过到。</p><p class="poem-stanza">固时俗之溷浊兮，志瞀迷而不知路。</p><p class="poem-stanza">念私门之正匠兮，遥涉江而远去。</p><p class="poem-stanza">念女嬃之婵媛兮，涕泣流乎于悒。</p><p class="poem-stanza">我决死而不生兮，虽重追吾何及。</p><p class="poem-stanza">戏疾濑之素水兮，望高山之蹇产。</p><p class="poem-stanza">哀高丘之赤岸兮，遂没身而不反。</p></div>',3)])])}const d=s(o,[["render",l]]);export{z as __pageData,d as default};
